package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(493L, result); // 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "01".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "008".getBytes(); // 8 is not octal
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidChar() {
        byte[] buffer = "00A".getBytes();
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_EmptyAfterSpaces() {
        byte[] buffer = "    ".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        byte[] buffer = "junk0007".getBytes();
        // offset 4, length 4 -> "0007"
        long result = TarUtils.parseOctal(buffer, 4, 4);
        assertEquals(7L, result);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Testing long capacity
        byte[] buffer = "777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 12);
        // 7 * (8^11 + 8^10 ... + 8^0)
        long expected = 0;
        for (int i = 0; i < 12; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, result);
    }

    @Test
    public void testParseOctal_OnlyDigits() {
        byte[] buffer = "01234567".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(5880L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonOctalRangeHigh() {
        byte[] buffer = "009".getBytes();
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonOctalRangeLow() {
        byte[] buffer = "00/".getBytes();
        TarUtils.parseOctal(buffer, 0, 3);
    }
}
